class Aseprite < Formula
  desc "Sprite animation and batch-export CLI (the pure-Rust aseprite port)"
  homepage "https://www.aseprite.org/"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/aseprite-0.0.1/aseprite-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/aseprite-0.0.1/aseprite-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/aseprite-0.0.1/aseprite-linux-amd64.tar.xz",
    ),
  )
  version "0.0.1"
  sha256 on_system_conditional(
    macos: "124237422cdb1cda21e89c084876ce2fe2e0ea90fcd162d22cb33f83b1b0ed9c",
    linux: on_arch_conditional(
      arm:   "017400597828a345489540232d8bc3710bbed4334b8dbe1fb901a478c1525f86",
      intel: "0638659f3906f5e0d53a1f9b70040387286472f7ba7cc828e7ccfccf4c8d6cd9",
    ),
  )
  license :cannot_represent

  def install
    bin.install "aseprite"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"aseprite"
      system "/usr/bin/xattr", "-cr", bin/"aseprite"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"aseprite"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/aseprite"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew aseprite at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed aseprite is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"aseprite") unless linked.symlink?
  end


  def caveats
    on_linux do
      <<~EOS
        aseprite ships as a single prebuilt binary per arch (every codec and the
        whole pixel engine are compiled in — no runtime downloads) and runs on
        ubuntu22 and newer (glibc >= 2.35). On hosts with glibc < 2.39 (Ubuntu 22.04
        and older), Homebrew adds gcc and glibc as implicit dependencies to every
        formula and would build them from source; aseprite's formula carries no real
        dependencies, so install it there with:

          brew install --ignore-dependencies aseprite

        On glibc >= 2.39 hosts (Ubuntu 24.04+, Homebrew's own supported set),
        plain `brew install aseprite` works with no extra pulls.
      EOS
    end
  end

  test do
    # The usage line survives argument changes; the version assert pins the
    # binary's self-report (the facade's version() — the module's 0.0.1, one
    # source of truth across crates).
    assert_match(/Usage: aseprite/, shell_output("#{bin}/aseprite --help"))
    assert_match(/^aseprite 0\.0\.1$/, shell_output("#{bin}/aseprite --version"))
  end
